class Solution:
    def firstMissingPositive(self, nums: list[int]) -> int:
        n = len(nums)

        for i in range(n):
            # 把 nums[i] 交换到下标 nums[i] - 1 处，直到它归位或落在 [1, n] 之外
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                v = nums[i]
                nums[i], nums[v - 1] = nums[v - 1], nums[i]

        for i in range(n):
            if nums[i] != i + 1:
                return i + 1

        return n + 1
